        if (t.is_temporary && t.original_order_type !== 'PRE_ORDER') return false;
      } else {
        if (t.is_temporary) return false;
      }
      if (orderType === 'DINE_IN' && activeDepartment !== 'All') {
        if (t.department_name !== activeDepartment) return false;
      }
      if (tableSearchQuery) {
        if (!t.table_name.toLowerCase().includes(tableSearchQuery.toLowerCase())) return false;
      }
      if (tableStatusFilter === 'AVAILABLE') {
        let status = tableStatuses[t.id] || 'AVAILABLE';
        const activeBillCount = (tableBills[t.id] || []).filter(item => !item.isCancelled).length;
        const hasCartItems = tableCarts[t.id]?.length > 0;
        if (activeBillCount > 0 && status === 'AVAILABLE') status = 'SAVED';
        if (hasCartItems) status = 'ITEMS_IN_KOT';
        if (status !== 'AVAILABLE') return false;
      } else if (tableStatusFilter === 'OCCUPIED') {
        let status = tableStatuses[t.id] || 'AVAILABLE';
        const activeBillCount = (tableBills[t.id] || []).filter(item => !item.isCancelled).length;
        const hasCartItems = tableCarts[t.id]?.length > 0;
        if (activeBillCount > 0 && status === 'AVAILABLE') status = 'SAVED';
        if (hasCartItems) status = 'ITEMS_IN_KOT';
        if (status === 'AVAILABLE') return false;
      }
      return true;
    });
  };"

